"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["47209"],{91858(e){e.exports=JSON.parse('{"id":"F384","slug":"expected-unexpected-loss","name":"Expected and Unexpected Credit Loss","subject":"Risk Management","section":"Risk","topic":"Probability of default, LGD, EAD","level":"Intermediate","aliases":["EL","UL","PD LGD EAD","loss given default","exposure at default"],"formula":{"latex":"EL=PD\\\\times LGD\\\\times EAD,\\\\quad UL=EAD\\\\sqrt{PD\\\\,\\\\sigma_{LGD}^{2}+LGD^{2}\\\\,PD(1-PD)}","also":[],"text":"Expected loss = PD x LGD x EAD; Unexpected loss = EAD x sqrt(PD x (LGD volatility)^2 + LGD^2 x PD x (1 - PD)); LGD = 1 - Recovery rate"},"symbols":[{"symbol":"PD","meaning":"Probability of default in the period","unit":"percent"},{"symbol":"LGD","meaning":"Loss given default, the share of the exposure lost if default occurs","unit":"percent"},{"symbol":"EAD","meaning":"Exposure at default, the amount owed when default happens","unit":"money"},{"symbol":"sigma_LGD","meaning":"Standard deviation of the loss given default","unit":"percent"}],"when_to_use":"Use it to size credit losses. Expected loss is the average, which should be covered by pricing and provisions. Unexpected loss is the standard deviation around it, which should be covered by capital. Regulators use PD, LGD and EAD as the inputs of the internal-ratings approach.","worked_example":{"problem":"A loan of 10 million has a 2% default probability, a recovery rate of 55% and a standard deviation of loss given default of 25%.","inputs":{"pd":2,"rec":55,"ead":10000000,"sl":25},"steps":[{"label":"LGD = 1 - recovery","working":"1-0.55","value":"45.0%"},{"label":"Expected loss = PD x LGD x EAD","working":"0.02 x 0.45 x 10,000,000","value":"90,000.00"},{"label":"Expected loss as a share of the loan","working":"0.02 x 0.45","value":"0.90%"},{"label":"Unexpected loss = EAD x sqrt(PD x sl^2 + LGD^2 x PD x (1 - PD))","working":"10,000,000 x sqrt(0.02 x 0.25^2+0.45^2 x 0.02 x (1-0.02))","value":"722,426.47"},{"label":"Unexpected / expected","working":"722426 / 90000","value":"8.0"}],"answer":"LGD is 45.0%. Expected loss is 90,000.00, or 0.90% of the loan. The unexpected loss is 722,426.47, about 8.0 times the expected loss, so capital must be held for a loss much bigger than the average."},"calculator":{"available":true,"inputs":[{"id":"pd","label":"Probability of default","unit":"%","type":"number","default":2,"hint":""},{"id":"rec","label":"Recovery rate","unit":"%","type":"number","default":55,"hint":""},{"id":"ead","label":"Exposure at default","unit":"money","type":"number","default":10000000,"hint":""},{"id":"sl","label":"Std dev of LGD","unit":"%","type":"number","default":25,"hint":""}],"checks":[{"expr":"pd>=0 and pd<=1 and rec>=0 and rec<=1","message":"The default probability and recovery rate must be between 0% and 100%."}],"steps":[{"id":"lgd","label":"LGD = 1 - recovery","expr":"1-rec","format":"pct1"},{"id":"el","label":"Expected loss = PD x LGD x EAD","expr":"pd*lgd*ead","format":"money"},{"id":"elp","label":"Expected loss as a share of the loan","expr":"pd*lgd","format":"pct2"},{"id":"ul","label":"Unexpected loss = EAD x sqrt(PD x sl^2 + LGD^2 x PD x (1 - PD))","expr":"ead*sqrt(pd*sl^2+lgd^2*pd*(1-pd))","format":"money"},{"id":"mult","label":"Unexpected / expected","expr":"ul/el","format":"num1"}],"results":["el","ul"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"lgd":0.45,"el":90000,"elp":0.009,"ul":722426.4668462806}},"finder":{"finds":"Average and variable credit losses","needs":"PD, recovery, exposure, LGD volatility"},"related":[{"slug":"default-probability-from-spread","name":"Default Probability and Recovery from Credit Spread"},{"slug":"recovery-rate","name":"Recovery Rate and Loss Given Default"},{"slug":"merton-model","name":"Merton Credit Model (Equity as a Call on Assets)"}],"related_ids":["F302","F202","F383"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>E</mi><mi>L</mi><mo>=</mo><mi>P</mi><mi>D</mi><mo>\xd7</mo><mi>L</mi><mi>G</mi><mi>D</mi><mo>\xd7</mo><mi>E</mi><mi>A</mi><mi>D</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>U</mi><mi>L</mi><mo>=</mo><mi>E</mi><mi>A</mi><mi>D</mi><msqrt><mrow><mi>P</mi><mi>D</mi><mtext>\u2009</mtext><msubsup><mi>\u03C3</mi><mrow><mi>L</mi><mi>G</mi><mi>D</mi></mrow><mn>2</mn></msubsup><mo>+</mo><mi>L</mi><mi>G</mi><msup><mi>D</mi><mn>2</mn></msup><mtext>\u2009</mtext><mi>P</mi><mi>D</mi><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>P</mi><mi>D</mi><mo stretchy=\\"false\\">)</mo></mrow></msqrt></mrow><annotation encoding=\\"application/x-tex\\">EL=PD\\\\times LGD\\\\times EAD,\\\\quad UL=EAD\\\\sqrt{PD\\\\,\\\\sigma_{LGD}^{2}+LGD^{2}\\\\,PD(1-PD)}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"expectations-theory","name":"Expectations Theory with a Liquidity Premium"},"next":{"slug":"high-yield-expected-return","name":"Expected Return after Defaults: Investment Grade vs. High Yield"},"lesson":null,"total":522}')}}]);